node -e "
const fs = require('fs');
const path = require('path');

const chapter = '${inputs.chapter}';
const description = '${inputs.description}';
const existingZones = '${nodes.load_zone_list.output.stdout || ''}'.split('\n').filter(f => f.endsWith('.yaml'));

// 分析需要创建的 Zone
const zonesNeeded = [];
const zonesPattern = /[CcZz][0-9]+[-_]?[Zz]?[0-9]*/g;
const matches = description.match(zonesPattern) || [];
matches.forEach(m => zonesNeeded.push(m.toUpperCase().replace('_', '-')));

// 确定任务拆分
const tasks = [];
const uniqueZones = [...new Set(zonesNeeded)];

uniqueZones.forEach(zoneId => {
  // 每个 Zone 需要: 1个策划任务 + 1个脚本任务
  tasks.push({
    type: 'level_design',
    role: 'L3_level_designer',
    zone_id: zoneId,
    title: '设计 ' + zoneId + ' 场景布局',
    priority: 1
  });
  tasks.push({
    type: 'scripting',
    role: 'L3_scripter',
    zone_id: zoneId,
    title: '编写 ' + zoneId + ' 脚本',
    priority: 2,
    depends_on: 'level_design_' + zoneId
  });
});

const result = {
  chapter,
  zones_needed: uniqueZones,
  existing_zones: existingZones.length,
  new_zones: uniqueZones.filter(z => !existingZones.some(e => e.includes(z))),
  tasks: tasks,
  total_tasks: tasks.length
};

console.log(JSON.stringify(result, null, 2));
"

node -e "
const fs = require('fs');
const path = require('path');

const analysis = JSON.parse('${nodes.analyze_scope.output.stdout}');
const taskId = '${inputs.task_id}';
const parentTitle = '${inputs.title}';
const projectRoot = '${inputs.project_root}';

const taskpackDir = path.join(projectRoot, 'design/ai-native/03_taskpacks/generated');
if (!fs.existsSync(taskpackDir)) fs.mkdirSync(taskpackDir, { recursive: true });

const generatedPacks = [];

analysis.tasks.forEach((task, idx) => {
  const subTaskId = taskId + '-' + (idx + 1).toString().padStart(2, '0');
  const packPath = path.join(taskpackDir, subTaskId + '.md');

  const content = '# TaskPack: ' + subTaskId + '\n\n' +
    '## 基本信息\n' +
    '- **父任务**: ' + taskId + '\n' +
    '- **标题**: ' + task.title + '\n' +
    '- **角色**: ' + task.role + '\n' +
    '- **类型**: ' + task.type + '\n' +
    '- **Zone**: ' + task.zone_id + '\n' +
    '- **优先级**: P' + task.priority + '\n\n' +
    '## 输入\n' +
    '- 父任务描述: ' + parentTitle + '\n' +
    '- Zone ID: ' + task.zone_id + '\n\n' +
    '## 交付物\n' +
    (task.type === 'level_design' 
      ? '- Zone 叙事布置文档\n- Zone 配置文件 (YAML)\n' 
      : '- Zone 脚本文件 (YAML)\n- 对白文件 (YAML)\n') +
    '\n## 验收标准\n' +
    '- [ ] 文件格式正确\n' +
    '- [ ] 符合设计规范\n' +
    '- [ ] 通过 CI 检查\n';

  fs.writeFileSync(packPath, content);
  generatedPacks.push({ id: subTaskId, path: packPath, role: task.role, zone: task.zone_id });
});

console.log(JSON.stringify({ generated: generatedPacks, count: generatedPacks.length }));
"
